<template><button @click="open" :disabled="busy">{{kind==='contracts'?'查看记录':'处理 / 审核'}}</button><Teleport to="body"><div v-if="opened" class="moderation-shade" @click.self="close"><section role="dialog" aria-modal="true" aria-label="平台审核" class="moderation-panel"><button class="close" @click="close">关闭 ×</button><h2>{{row.title||row.username||'处理记录 #'+row.id}}</h2><p v-if="error" role="alert">{{error}}</p><p v-if="busy">正在处理……</p><template v-if="details"><h3>房源信息</h3><p>{{details.house.city}} {{details.house.district}} {{details.house.address}} · ¥{{details.house.price}}/月</p><p>{{details.house.description}}</p><template v-if="details.application"><h3>出租资格与费用</h3><p>申请人：{{details.application.applicant_name}} · {{details.application.publisher_type==='OWNER'?'产权人':'受托人'}}</p><p>押{{details.application.deposit_months}}付{{details.application.payment_months}} · 服务费{{details.application.service_fee}}元</p><p>{{details.application.other_fees}}；{{details.application.utility_terms}}</p></template><p v-else>发布者尚未提交完整出租资格材料，不能通过审核。</p><div class="materials"><button v-for="f in details.files" :key="f.id" @click="preview(f)">{{kindLabel(f.kind)}} · 查看</button></div><p v-if="details.duplicatePhotos?.length">有{{details.duplicatePhotos.length}}条与其他房源完全相同的照片，请核查。</p><ul><li v-for="(h,i) in details.history" :key="i">{{h.createdAt}} · {{h.note}}</li></ul></template><p v-else-if="kind==='reports'">{{row.category}}：{{row.content}}</p><p v-else>{{row.content||row.title}}</p>
<div v-if="kind==='reports'" class="materials"><RouterLink :to="'/detail/'+row.house_id">查看被举报房源 ↗</RouterLink><button v-for="id in evidenceIds()" :key="id" @click="preview({id})">查看举报证据</button></div><iframe v-if="fileUrl" :src="fileUrl" title="审核材料预览"/><template v-if="kind!=='contracts'"><label>处理结果<select v-model="status"><template v-if="kind==='houses'"><option value="APPROVED">审核通过并上架</option><option value="REJECTED">退回修改</option><option value="OFFLINE">下架</option></template><template v-else-if="kind==='users'"><option value="0">停用账号并下架其公开房源</option><option value="1">恢复账号</option></template><template v-else-if="kind==='reports'"><option value="RESOLVED">采纳举报</option><option value="DISMISSED">不采纳举报</option></template><template v-else><option :value="kind==='guides'?'published':'APPROVED'">审核通过</option><option value="REJECTED">退回修改</option><option value="OFFLINE">下架内容</option></template></select></label><div v-if="kind==='houses'&&status==='APPROVED'"><label v-for="(label,key) in checks" :key="key"><input type="checkbox" v-model="checked[key]"/>{{label}}</label></div><label v-if="kind==='reports'"><input type="checkbox" v-model="takeOffline"/>同时下架该房源（仅采纳举报时）</label><label>处理原因（会反馈给当事用户）<textarea v-model.trim="note" maxlength="1000" rows="4"/></label><button class="jade-button" :disabled="busy||!note" @click="save">确认处理并通知用户</button></template></section></div></Teleport></template>
<script setup>
import {ref,reactive,onBeforeUnmount} from 'vue'
import request from '../api/index'
const props=defineProps({row:Object,kind:String}),emit=defineEmits(['changed']),opened=ref(false),busy=ref(false),error=ref(''),details=ref(null),status=ref(''),note=ref(''),takeOffline=ref(false),fileUrl=ref(''),checked=reactive({identityChecked:false,propertyChecked:false,listingChecked:false}),checks={identityChecked:'已核对身份材料与申请人一致',propertyChecked:'已核对权属地址及出租授权关系',listingChecked:'已核对照片、地址、租金与费用披露'}
const kindLabel=k=>({IDENTITY:'身份材料',PROPERTY:'权属材料',AUTHORIZATION:'授权书',PHOTO:'房源照片',EVIDENCE:'举报证据'}[k]||k)
function close(){if(busy.value)return;opened.value=false;URL.revokeObjectURL(fileUrl.value);fileUrl.value=''}
async function open(){opened.value=true;error.value='';note.value='';status.value={houses:'REJECTED',users:props.row.status===1?'0':'1',reports:'RESOLVED',guides:'published',reviews:'APPROVED'}[props.kind]||'';Object.keys(checked).forEach(k=>checked[k]=false);details.value=null;takeOffline.value=false;if(props.kind==='houses'){busy.value=true;try{details.value=(await request.get('/trust/application/'+props.row.id)).data}catch(e){error.value=e.message}finally{busy.value=false}}}
function evidenceIds(){try{return JSON.parse(props.row.evidence_ids||'[]')}catch{return []}}
async function preview(f){error.value='';try{const bytes=await request.get('/trust/files/'+f.id,{responseType:'blob'});URL.revokeObjectURL(fileUrl.value);fileUrl.value=URL.createObjectURL(bytes)}catch(e){error.value='材料加载失败，请稍后重试'}}
async function save(){busy.value=true;error.value='';try{let path,body={status:status.value,note:note.value,...checked};if(props.kind==='houses')path='/trust/review/'+props.row.id;else if(props.kind==='reports'){path='/trust/reports/'+props.row.id;body={status:status.value,response:note.value,takeOffline:takeOffline.value}}else{path='/admin/'+{users:'user',reviews:'review',guides:'guide'}[props.kind]+'/'+props.row.id+'/status';if(props.kind==='users')body.status=Number(body.status)}await request[{houses:'post',reports:'post'}[props.kind]||'put'](path,body);opened.value=false;emit('changed')}catch(e){error.value=e.response?.data?.message||e.message}finally{busy.value=false}}
onBeforeUnmount(()=>URL.revokeObjectURL(fileUrl.value))
</script>
<style scoped>button{padding:8px 12px;border:1px solid var(--jade-line);background:white;border-radius:4px;color:var(--jade-700)}.moderation-shade{position:fixed;inset:0;background:#102b27aa;z-index:3000;display:flex;align-items:center;justify-content:center;padding:24px}.moderation-panel{background:var(--jade-paper);padding:30px;max-width:900px;width:100%;max-height:90dvh;overflow:auto;border-radius:10px;color:var(--jade-ink)}.close{float:right}.moderation-panel h2,.moderation-panel h3{margin:18px 0}.moderation-panel p,.moderation-panel li{font-size:14px;line-height:1.9;white-space:pre-wrap}.moderation-panel label{display:block;line-height:2;margin:15px 0;font-size:14px}.moderation-panel select,.moderation-panel textarea{display:block;width:100%;padding:10px;border:1px solid var(--jade-line);border-radius:4px;background:white}.moderation-panel input{margin-right:8px}.moderation-panel iframe{width:100%;height:420px;border:1px solid var(--jade-line);margin:18px 0}.materials{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0}</style>
